  private _gpupPx = new Uint8Array(4);
  /** §319 上一条云 march 距离的裁剪读数(报告/`vcloud rayauto` 用) */
  private _tcRayInfo: { userRay: number; bound: number; eff: number; auto: boolean; clamp?: boolean; culled: boolean; skyFrac?: number } | null = null;
  /** §323 质量档: full=普通 / sky=天空为主(按占比缩步数) / none=整个视锥都够不到 */
  private _tcTier: 'full' | 'sky' | 'none' | null = null;

  /**
   * §319: 云 march 距离的**保守上界**(米) —— 由"相机高度 + 云层带 + 视锥方向"决定。
   *
   * 单层带 [base, top] 下, 一条方向为 d(dy = d.y) 的光线能碰到云的最远距离:
   *   dy > 0 (向上): 相机在层顶之下才可能入层 ⇒ 最远到**层顶**: (top - h)/dy; 在层顶之上 ⇒ **0**(永远碰不到)
   *   dy < 0 (向下): 相机在层底之上才可能入层 ⇒ 最远到**层底**: (base - h)/dy; 在层底之下 ⇒ **0**
   *   dy ≈ 0 (水平): 只有相机在带内才有云 ⇒ 带内 Infinity(不设限) / 带外 0
   * 取视锥四角(含跨水平时)的上界再取 **max** ⇒ 不会裁掉任何可能有云的像素。
   * 值随相机姿态**连续变化**(不会跳变导致云突然消失); 极端情况下限 400m(见调用处)。
   */
  private cloudRayBoundM(): number {
    const bands = this._tcBandsCache;
    if (!bands || !bands.length) return Infinity;
    let base = Infinity; let top = -Infinity;
    for (const b of bands) {
      if (!(b.height > 0)) continue;
      base = Math.min(base, b.altitude);
      top = Math.max(top, b.altitude + b.height);
    }
    if (!Number.isFinite(base) || !Number.isFinite(top) || top <= base) return Infinity;
    const cam = this.camera.camera;
    const h = cam.position.y;
    // 视锥四角的世界方向(相机内参 + 姿态都已就绪; 用 unproject 拿到方向, 与渲染口径一致)
    const dirs: Array<{ x: number; y: number; z: number }> = [];
    for (const [sx, sy] of [[-1, -1], [1, -1], [-1, 1], [1, 1]] as Array<[number, number]>) {
      const v3Ray = this._rayBoundV.set(sx, sy, 0.5).unproject(cam).sub(cam.position);
      if (v3Ray.lengthSq() < 1e-9) continue;
      v3Ray.normalize();
      dirs.push({ x: v3Ray.x, y: v3Ray.y, z: v3Ray.z });
    }
    if (dirs.length === 0) return Infinity;

    // === 球壳求交上界(替换原来的"按方向 Y 的平面模型") =============================
    // 旧实现 `useful(dy) = (top − h)/dy`, 平面模型: dy→0⁺ 时 →∞, 而视锥**只要跨过水平线**
    // 就拿不到有限上界 ⇒ bound=Infinity ⇒ 整帧按 userRay 走(现场设 119km)、每个像素把
    // 150 步跑满 ⇒ 症状就是"高于云层后向远处大幅拓展 + 变卡"(实测)。
    // 真实几何里 dy≈0 的射线在球面上**不会**停在原高度: 地球曲率会把它带离这一层 ⇒
    // "到云层的距离"本来就是**有限**的。球壳求交天然给出这个有限上界, 地平线附近也有。
    // 数学: |o + t·d| = R + targetH, o = (0, R+h, 0) ⇒ t = −b + √(b²−c),
    //       b = o·d = oy·d.y, c = |o|² − (R+targetH)²   (x/z 不进 b/c, 只需 y 对齐)
    // 取 `−b + √` 是**远交点**(相机在壳内时另一根为负) ⇒ 正好是"出云层"的距离。
    const R = 6378137;                       // 椭球赤道半径, 与 clouds-takram.setWorldFrame 一致
    const oy = R + h;
    const oy2 = oy * oy;
    const hitFar = (targetH: number, d: { y: number }): number => {
      const r = R + targetH;
      const c = oy2 - r * r;
      const b = oy * d.y;
      const disc = b * b - c;
      if (disc < 0) return Infinity;         // 这个方向永远到不了该半径
      const t = -b + Math.sqrt(disc);
      return t > 0 ? t : Infinity;
    };
    // 上界 = 视锥四角里"出云层"最远的那条(出层 = 层底/层顶两壳里更远的那个出口)
    let bound = 0;
    for (const d of dirs) {
      const tOut = Math.max(hitFar(base, d), hitFar(top, d));
      if (Number.isFinite(tOut) && tOut > bound) bound = tOut;
    }
    // 四角都碰不到云层 ⇒ 整 pass 可以跳过(交给上层 culled 判定)
    if (bound <= 0) return 0;
    return bound * 1.15;   // 15% 余量(云团边缘/凸起不至于被切)
  }

  /** 能量 AI 的手感常数(现场可调: `ai g|corner|thrust|drag|induced|roll|lag|aoa <v>`) */
  private aiEnergyTuning(): Partial<typeof AI_TUNING_DEFAULT> {
    const get = (k: string, def: number, lo: number, hi: number) => {
      const raw = this.lsGet(`skybound.ai${k}`);
      if (raw === null || raw.trim() === '') return def;
      const v = Number(raw);
      return Number.isFinite(v) && v >= lo && v <= hi ? v : def;
    };
    return {
      maxG: get('MaxG', AI_TUNING_DEFAULT.maxG, 2, 12),
      cornerFrac: get('Corner', AI_TUNING_DEFAULT.cornerFrac, 0.35, 0.9),
      thrust: get('Thrust', AI_TUNING_DEFAULT.thrust, 3, 40),
      dragK: get('Drag', AI_TUNING_DEFAULT.dragK, 1e-6, 3e-4),
      inducedK: get('Induced', AI_TUNING_DEFAULT.inducedK, 0, 2),
      rollK: get('Roll', AI_TUNING_DEFAULT.rollK, 0.3, 5),
      lagBaseM: get('Lag', AI_TUNING_DEFAULT.lagBaseM, 0, 2000),
      aoaDeg: get('Aoa', AI_TUNING_DEFAULT.aoaDeg, 0, 12),
    };
  }
